#include <stdio.h>

int changed(int value)
{
    value = 99;
    return value;
}

int main(void)
{
    int x = 3;
    printf("%d\n", changed(x));
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

int larger(int a, int b)
{
    if (a > b) { return a; }
    return b;
}

int main(void)
{
    printf("%d\n", larger(3, 8));
    return 0;
}

#include <stdio.h>

int is_even(int n)
{
    return n % 2 == 0;
}

int main(void)
{
    printf("%d %d\n", is_even(-4), is_even(3));
    return 0;
}

